@page "/notepad"
@rendermode InteractiveServer
@inject IJSRuntime JS
@implements IAsyncDisposable

<PageTitle>Notepad</PageTitle>

<h1>Notepad</h1>

<textarea @ref="_textareaRef" @oninput="OnInput" rows="15" cols="80">@_content</textarea>

<div style="margin-top: 0.5rem;">
    <button @onclick="SaveNowAsync">Save now</button>
    <button @onclick="ClearAsync">Clear</button>
</div>

@if (_lastSavedAt is not null)
{
    <p>Last saved at @_lastSavedAt</p>
}

@code {
    private ElementReference _textareaRef;
    private NotepadInterop? _interop;
    private DotNetObjectReference<Notepad>? _dotNetRef;

    private string _content = string.Empty;
    private string? _lastSavedAt;
    private bool _hasUnsavedChanges;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _dotNetRef = DotNetObjectReference.Create(this);
            _interop = new NotepadInterop(JS);
            var result = await _interop.InitializeAsync(_dotNetRef);
            _content = result.Content ?? string.Empty;
            _lastSavedAt = result.LastSavedAt;
            StateHasChanged();
        }
    }

    private void OnInput(ChangeEventArgs e)
    {
        _content = e.Value?.ToString() ?? string.Empty;
        _hasUnsavedChanges = true;
    }

    private async Task SaveNowAsync()
    {
        if (_interop is not null)
        {
            await _interop.SaveAsync(_content);
            _lastSavedAt = DateTime.Now.ToString("HH:mm:ss");
            _hasUnsavedChanges = false;
        }
    }

    private async Task ClearAsync()
    {
        if (_interop is not null)
        {
            _content = string.Empty;
            _hasUnsavedChanges = false;
            _lastSavedAt = null;
            await _interop.ClearAsync();
        }
    }

    [JSInvokable]
    public async Task OnAutoSave()
    {
        await InvokeAsync(() =>
        {
            _lastSavedAt = DateTime.Now.ToString("HH:mm:ss");
            _hasUnsavedChanges = false;
            StateHasChanged();
        });
    }

    public async ValueTask DisposeAsync()
    {
        try
        {
            if (_interop is not null)
                await _interop.DisposeAsync();
        }
        catch (JSDisconnectedException) { }

        _dotNetRef?.Dispose();
    }
}

const STORAGE_KEY = 'notepad-content';
const STORAGE_TIME_KEY = 'notepad-saved-at';
const AUTO_SAVE_INTERVAL_MS = 30000;
const ON_AUTO_SAVE = 'OnAutoSave';

let dotNetRef;
let intervalId;
let textareaEl;

export function initialize(dotNetReference, textareaElement) {
    dotNetRef = dotNetReference;
    textareaEl = textareaElement;

    window.addEventListener('beforeunload', onBeforeUnload);

    intervalId = setInterval(async () => {
        await autoSave();
    }, AUTO_SAVE_INTERVAL_MS);

    const content = localStorage.getItem(STORAGE_KEY) || '';
    const savedAt = localStorage.getItem(STORAGE_TIME_KEY) || null;
    return { content, savedAt };
}

async function autoSave() {
    if (!textareaEl) return;
    const content = textareaEl.value;
    localStorage.setItem(STORAGE_KEY, content);
    const time = new Date().toLocaleTimeString('en-GB', { hour12: false });
    localStorage.setItem(STORAGE_TIME_KEY, time);
    try {
        await dotNetRef.invokeMethodAsync(ON_AUTO_SAVE);
    } catch { /* circuit disconnected */ }
}

function onBeforeUnload(e) {
    if (!textareaEl) return;
